"use client"

import { generatedQuote, quoteDraft, reviewSections, transcriptDemo } from "@/lib/quote-data"
import { supabase } from "@/lib/supabase"

function getReviewField(sectionId: string) {
  const section = reviewSections.find((item) => item.id === sectionId)
  return section?.value ?? ""
}

function getJobType() {
  const jobType = getReviewField("jobtype")
  return jobType.split("\n")[0] || "Generated Quote"
}

export async function saveGeneratedQuoteDraft() {
  const {
    data: { user },
    error: userError,
  } = await supabase.auth.getUser()

  if (userError || !user) {
    return {
      ok: false,
      message: userError?.message ?? "You must be signed in to save a draft.",
    }
  }

  const { error } = await supabase.from("quote_drafts").insert({
    user_id: user.id,
    client_name: quoteDraft.client.name,
    site_address: quoteDraft.client.address,
    quote_title: `${getJobType()} - ${quoteDraft.quoteNo}`,
    job_type: getJobType(),
    raw_transcript: transcriptDemo,
    quote_sections: reviewSections,
    line_items: generatedQuote.lineItems,
    status: "Needs Review",
  })

  if (error) {
    return {
      ok: false,
      message: error.message,
    }
  }

  return {
    ok: true,
    message: "Draft saved to Supabase.",
  }
}
